// Update parseRawToolCall to check custom tools
export function parseRawToolCall<T extends ToolName = ToolName>(
  rawToolCall: {
    toolName: T
    toolCallId: string
    input: Record<string, unknown>
  },
  autoInsertEndStepParam: boolean = false,
  fileContext?: ProjectFileContext,
): CodebuffToolCall<T> | ToolCallError {
  const toolName = rawToolCall.toolName

  // Check built-in tools first
  const builtInTool = codebuffToolDefs[toolName as ToolName]
  const customTool = fileContext?.customToolDefinitions?.[toolName]

  if (!builtInTool && !customTool) {
    return {
      toolName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Tool ${toolName} not found`,
    }
  }

  const toolDef = builtInTool || customTool
  const validName = toolName as T

  const processedParameters: Record<string, any> = {}
  for (const [param, val] of Object.entries(rawToolCall.input ?? {})) {
    processedParameters[param] = val
  }

  if (autoInsertEndStepParam) {
    processedParameters[endsAgentStepParam] = toolDef.endsAgentStep
  }

  const paramsSchema = toolDef.endsAgentStep
    ? (toolDef.parameters satisfies z.ZodObject as z.ZodObject).extend({
        [endsAgentStepParam]: z.literal(toolDef.endsAgentStep),
      })
    : toolDef.parameters
  const result = paramsSchema.safeParse(processedParameters)

  if (!result.success) {
    return {
      toolName: validName,
      toolCallId: rawToolCall.toolCallId,
      input: rawToolCall.input,
      error: `Invalid parameters for ${validName}: ${JSON.stringify(
        result.error.issues,
        null,
        2,
      )}`,
    }
  }

  if (endsAgentStepParam in result.data) {
    delete result.data[endsAgentStepParam]
  }

  return {
    toolName: validName,
    input: result.data,
    toolCallId: rawToolCall.toolCallId,
  } as CodebuffToolCall<T>
}

// Update executeToolCall signature and implementation
export function executeToolCall<T extends ToolName>({
  toolName,
  input,
  toolCalls,
  toolResults,
  previousToolCallFinished,
  ws,
  agentTemplate,
  fileContext,
  agentStepId,
  clientSessionId,
  userInputId,
  fullResponse,
  onResponseChunk,
  state,
  userId,
  autoInsertEndStepParam = false,
}: ExecuteToolCallParams<T>): Promise<void> {
  const toolCall: CodebuffToolCall<T> | ToolCallError = parseRawToolCall<T>(
    {
      toolName,
      toolCallId: generateCompactId(),
      input,
    },
    autoInsertEndStepParam,
    fileContext, // Pass fileContext
  )

  if ('error' in toolCall) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: toolCall.error,
      },
    })
    logger.debug(
      { toolCall, error: toolCall.error },
      `${toolName} error: ${toolCall.error}`,
    )
    return previousToolCallFinished
  }

  onResponseChunk({
    type: 'tool_call',
    toolCallId: toolCall.toolCallId,
    toolName,
    input: toolCall.input,
  })

  logger.debug(
    { toolCall },
    `${toolName} (${toolCall.toolCallId}) tool call detected in stream`,
  )
  toolCalls.push(toolCall)

  if (!agentTemplate.toolNames.includes(toolCall.toolName)) {
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Tool \`${toolName}\` is not currently available. Make sure to only use tools listed in the system instructions.`,
      },
    })
    return previousToolCallFinished
  }

  // Check if this is a built-in tool or custom tool
  const handler = codebuffToolHandlers[toolName as ToolName]

  if (!handler) {
    // This is a custom tool - handle it specially
    toolResults.push({
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text',
        value: `Custom tool ${toolName} executed with input: ${JSON.stringify(toolCall.input)}`,
      },
    })
    return previousToolCallFinished
  }

  // Execute built-in tool as before
  const { result: toolResultPromise, state: stateUpdate } = (
    handler as CodebuffToolHandlerFunction<T>
  )({
    previousToolCallFinished,
    fileContext,
    agentStepId,
    clientSessionId,
    userInputId,
    fullResponse,
    writeToClient: onResponseChunk,
    requestClientToolCall: async (
      clientToolCall: ClientToolCall<T extends ClientToolName ? T : never>,
    ) => {
      if (!checkLiveUserInput(userId, userInputId, clientSessionId)) {
        return ''
      }

      const clientToolResult = await requestToolCall(
        ws,
        userInputId,
        clientToolCall.toolName,
        clientToolCall.input,
      )
      return (
        clientToolResult.error ??
        (clientToolResult.output?.type === 'text'
          ? clientToolResult.output.value
          : 'undefined')
      )
    },
    toolCall,
    getLatestState: () => state,
    state,
  })

  for (const [key, value] of Object.entries(stateUpdate ?? {})) {
    if (key === 'agentState' && typeof value === 'object' && value !== null) {
      state.agentState = value
    } else {
      state[key] = value
    }
  }

  return toolResultPromise.then((result) => {
    const toolResult = {
      toolName,
      toolCallId: toolCall.toolCallId,
      output: {
        type: 'text' as const,
        value: result as string,
      },
    }
    logger.debug(
      { toolResult },
      `${toolName} (${toolResult.toolCallId}) tool result for tool`,
    )
    if (result === undefined) {
      return
    }

    onResponseChunk({
      type: 'tool_result',
      toolCallId: toolResult.toolCallId,
      output: toolResult.output,
    })

    toolResults.push(toolResult)

    state.messages.push({
      role: 'user' as const,
      content: asSystemMessage(renderToolResults([toolResult])),
    })
  })
}
