```typescript
/**
 * Utility functions for parsing agent IDs in various formats
 */

export interface ParsedAgentId {
  publisherId?: string
  agentId?: string
  version?: string
}

export interface ParsedPublishedAgentId {
  publisherId: string
  agentId: string
  version?: string
}

/**
 * Parse agent ID in multiple formats:
 * - publisher/agentId[@version] (full format with publisher)
 * - agentId[@version] (agent ID only, for backward compatibility)
 * 
 * Returns an object with optional publisherId, agentId, and version properties.
 * If parsing fails or inputs are invalid, returns an object with undefined values.
 */
export function parseAgentId(fullAgentId: string): ParsedAgentId {
  if (!fullAgentId || typeof fullAgentId !== 'string') {
    return {}
  }

  const parts = fullAgentId.split('/')

  if (parts.length === 2) {
    const [publisherId, agentNameWithVersion] = parts

    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { publisherId, agentId, version }
    }

    return { publisherId, agentId: agentNameWithVersion }
  }

  if (parts.length === 1) {
    const agentNameWithVersion = parts[0]

    const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
    if (versionMatch) {
      const [, agentId, version] = versionMatch
      return { agentId, version }
    }

    return { agentId: agentNameWithVersion }
  }

  return {}
}

/**
 * Parse agent ID that must be in the full publisher/agent format.
 * Returns null if the agent ID is not in the required publisher/agent format.
 * When successful, returns an object with required publisherId and agentId properties,
 * and an optional version property.
 */
export function parsePublishedAgentId(
  fullAgentId: string
): ParsedPublishedAgentId | null {
  if (!fullAgentId || typeof fullAgentId !== 'string') {
    return null
  }

  const parts = fullAgentId.split('/')
  if (parts.length !== 2) {
    return null
  }

  const [publisherId, agentNameWithVersion] = parts

  const versionMatch = agentNameWithVersion.match(/^(.+)@(.+)$/)
  if (versionMatch) {
    const [, agentId, version] = versionMatch
    return { publisherId, agentId, version }
  }

  return { publisherId, agentId: agentNameWithVersion }
}
