### 2. Create new matching utility in `common/src/util/agent-template-validation.ts`

Add a new function to handle sophisticated agent ID matching:

```typescript
/**
 * Matches a child agent ID against spawnable agent patterns with flexible matching rules.
 * Supports matching scenarios including:
 * - Exact matches (publisher, agent, version all match)
 * - Publisher and agent match when child has no version specified
 * - Agent and version match when child has no publisher specified
 * - Agent name only match when child has neither publisher nor version
 * 
 * @param childAgentId - The agent ID being spawned (e.g., "publisher/agent@1.0.0", "agent", "agent@1.0.0")
 * @param spawnableAgents - List of spawnable agent patterns
 * @param parseAgentId - Function to parse agent IDs into components
 * @returns The matching spawnable agent ID if found, or null if no match exists
 */
export function matchSpawnableAgent(
  childAgentId: string,
  spawnableAgents: string[],
  parseAgentId: (id: string) => {
    publisherId: string
    agentId: string
    version?: string
  } | null,
): string | null {
  const childParsed = parseAgentId(childAgentId)

  // If child ID doesn't parse, try direct string match as fallback
  if (!childParsed) {
    return spawnableAgents.includes(childAgentId) ? childAgentId : null
  }

  for (const spawnableAgent of spawnableAgents) {
    const spawnableParsed = parseAgentId(spawnableAgent)

    // If spawnable doesn't parse, try direct string match
    if (!spawnableParsed) {
      if (spawnableAgent === childAgentId) {
        return spawnableAgent
      }
      continue
    }

    const { publisherId: childPub, agentId: childAgent, version: childVer } = childParsed
    const { publisherId: spawnPub, agentId: spawnAgent, version: spawnVer } = spawnableParsed

    // Exact match: publisher, agent, and version all match
    if (childPub === spawnPub && childAgent === spawnAgent && childVer === spawnVer) {
      return spawnableAgent
    }

    // Publisher and agent match when child has no version
    if (childPub === spawnPub && childAgent === spawnAgent && !childVer) {
      return spawnableAgent
    }

    // Agent and version match when child has no publisher (but spawnable does)
    if (childAgent === spawnAgent && childVer === spawnVer && !childPub && spawnPub) {
      return spawnableAgent
    }

    // Agent name only match when child has neither publisher nor version
    if (childAgent === spawnAgent && !childVer && !childPub) {
      return spawnableAgent
    }
  }

  return null
}
