'use client'

import { useEffect, useRef, useState } from 'react'

import { DocSidebar } from './doc-sidebar'
import { cn } from '@/lib/utils'

export function EnhancedDocSidebar({
  className,
  onNavigate,
}: {
  className?: string
  onNavigate: () => void
}) {
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const [showTopFade, setShowTopFade] = useState(false)
  const [showBottomFade, setShowBottomFade] = useState(false)

  useEffect(() => {
    const scrollContainer = scrollContainerRef.current
    if (!scrollContainer) return

    const updateFadeVisibility = () => {
      const { scrollTop, scrollHeight, clientHeight } = scrollContainer
      const isScrolledFromTop = scrollTop > 10
      const isScrolledFromBottom = scrollTop < scrollHeight - clientHeight - 10

      setShowTopFade(isScrolledFromTop)
      setShowBottomFade(isScrolledFromBottom)
    }

    updateFadeVisibility()

    scrollContainer.addEventListener('scroll', updateFadeVisibility)
    return () => scrollContainer.removeEventListener('scroll', updateFadeVisibility)
  }, [])

  return (
    <div className="relative">
      <div
        ref={scrollContainerRef}
        className={cn(
          'doc-sidebar-scrollable fixed top-24 w-64 h-[calc(100vh-12rem)] overflow-y-auto pr-4 z-40',
          'bg-background/40 backdrop-blur-sm border border-border/50 rounded-lg shadow-lg p-4',
          className
        )}
      >
        <DocSidebar className="" onNavigate={onNavigate} />
      </div>

      {showTopFade && (
        <div
          className="hidden lg:block fixed top-24 w-64 h-16 pointer-events-none z-50 rounded-t-lg transition-opacity duration-300"
          style={{
            background: 'linear-gradient(to bottom, hsl(var(--background)) 0%, transparent 100%)',
          }}
        />
      )}

      {showBottomFade && (
        <div
          className="hidden lg:block fixed w-64 h-16 pointer-events-none z-50 rounded-b-lg transition-opacity duration-300"
          style={{
            top: 'calc(100vh - 12rem - 4rem)',
            background: 'linear-gradient(to top, hsl(var(--background)) 0%, transparent 100%)',
          }}
        />
      )}
    </div>
  )
}
