### 1. Create a new utility hook for hash navigation

**File: `web/src/hooks/use-hash-navigation.tsx`** (new file)

```tsx
'use client'

import { useEffect } from 'react'

export function useHashNavigation() {
  useEffect(() => {
    const scrollToHash = (hash: string, pushState = false) => {
      if (!hash) return

      const id = hash.replace('#', '')
      const element = document.getElementById(id)

      if (element) {
        element.scrollIntoView({ behavior: 'smooth' })

        if (pushState) {
          window.history.pushState(null, '', `${window.location.pathname}${hash}`)
        }
      }
    }

    const handleInitialHash = () => {
      if (window.location.hash) {
        setTimeout(() => {
          scrollToHash(window.location.hash, false)
        }, 100)
      }
    }

    const handlePopState = () => {
      if (window.location.hash) {
        scrollToHash(window.location.hash, false)
      }
    }

    const handleHashChange = () => {
      if (window.location.hash) {
        scrollToHash(window.location.hash, false)
      }
    }

    handleInitialHash()

    window.addEventListener('popstate', handlePopState)
    window.addEventListener('hashchange', handleHashChange)

    return () => {
      window.removeEventListener('popstate', handlePopState)
      window.removeEventListener('hashchange', handleHashChange)
    }
  }, [])
}

export function navigateToHash(id: string) {
  const element = document.getElementById(id)

  if (element) {
    element.scrollIntoView({ behavior: 'smooth' })
    window.history.pushState(null, '', `${window.location.pathname}#${id}`)
  }
}
```

