  messages,
}: {
  runState: RunState
  messages: CodebuffMessage[]
}): RunState {
  // Deep copy
  const newRunState = JSON.parse(JSON.stringify(runState)) as typeof runState

  newRunState.sessionState.mainAgentState.messageHistory = messages

  return newRunState
}
