import type { Request as ExpressRequest } from 'express'

/**
 * Extracts the authentication token from the x-codebuff-api-key header
 * @param req - Express request object
 * @returns The auth token if present, undefined otherwise
 */
export function extractAuthToken(req: ExpressRequest): string | undefined {
  const apiKey = req.headers['x-codebuff-api-key']

  if (typeof apiKey === 'string' && apiKey.trim()) {
    return apiKey.trim()
  }

  return undefined
}
