import { API_KEY_ENV_VAR } from '@codebuff/common/constants'

import type { User } from '@codebuff/common/util/credentials'

/**
 * Gets the authentication token from user credentials or environment variables
 * @param user - Optional user object with authToken
 * @returns The auth token if available, undefined otherwise
 */
export function getAuthToken(user?: User): string | undefined {
  return process.env[API_KEY_ENV_VAR] || user?.authToken
}

/**
 * Creates headers object with x-codebuff-api-key header for API requests
 * @param user - Optional user object with authToken
 * @param additionalHeaders - Optional additional headers to include
 * @returns Headers object with authentication
 */
export function createAuthHeaders(
  user?: User,
  additionalHeaders?: Record<string, string>,
): Record<string, string> {
  const authToken = getAuthToken(user)
  const headers: Record<string, string> = {
    ...additionalHeaders,
  }

  if (authToken) {
    headers['x-codebuff-api-key'] = authToken
  }

  return headers
}

/**
 * Adds x-codebuff-api-key header to existing headers object
 * @param headers - Existing headers object
 * @param user - Optional user object with authToken
 * @returns Updated headers object
 */
export function addAuthHeader(
  headers: Record<string, string>,
  user?: User,
): Record<string, string> {
  const authToken = getAuthToken(user)

  if (authToken) {
    return {
      ...headers,
      'x-codebuff-api-key': authToken,
    }
  }

  return headers
}
