import { AGENT_PERSONAS } from '@codebuff/common/constants/agents'
import { Request, Response, NextFunction } from 'express'
import { z } from 'zod/v4'
import { getAgentTemplate } from '../templates/agent-registry'
import { logger } from '../util/logger'

const validateAgentNameSchema = z.object({
  agentId: z.string().min(1),
})

// 5-minute cache for positive validation results
const validationCache = new Map<string, { valid: boolean; source: 'builtin' | 'published'; normalizedId: string; timestamp: number }>()
const CACHE_TTL = 5 * 60 * 1000 // 5 minutes in milliseconds

function getCachedValidation(agentId: string) {
  const cached = validationCache.get(agentId)
  if (!cached) return null

  const now = Date.now()
  if (now - cached.timestamp > CACHE_TTL) {
    validationCache.delete(agentId)
    return null
  }

  return cached
}

function setCachedValidation(agentId: string, result: { valid: boolean; source: 'builtin' | 'published'; normalizedId: string }) {
  validationCache.set(agentId, {
    ...result,
    timestamp: Date.now(),
  })
}

export async function validateAgentNameHandler(
  req: Request,
  res: Response,
  next: NextFunction,
) {
  try {
    // Log authentication headers for debugging
    const authHeader = req.headers.authorization
    const apiKeyHeader = req.headers['x-api-key']

    if (authHeader || apiKeyHeader) {
      logger.debug(
        {
          hasAuthHeader: !!authHeader,
          hasApiKeyHeader: !!apiKeyHeader,
        },
        'Agent validation request with authentication headers',
      )
    }

    // Validate query parameters
    const parseResult = validateAgentNameSchema.safeParse(req.query)

    if (!parseResult.success) {
      return res.status(400).json({
        valid: false,
        message: 'Invalid request',
        issues: parseResult.error.issues,
      })
    }

    const { agentId } = parseResult.data

    // Check cache first
    const cached = getCachedValidation(agentId)
    if (cached) {
      logger.debug({ agentId, source: cached.source }, 'Agent validation cache hit')
      return res.json({
        valid: cached.valid,
        source: cached.source,
        normalizedId: cached.normalizedId,
      })
    }

    // Check builtin agents first
    if (agentId in AGENT_PERSONAS) {
      const result = {
        valid: true,
        source: 'builtin' as const,
        normalizedId: agentId,
      }
      setCachedValidation(agentId, result)
      logger.debug({ agentId }, 'Agent validated as builtin')
      return res.json(result)
    }

    // Check published agents via agent registry
    const agentTemplate = await getAgentTemplate(agentId, {})

    if (agentTemplate) {
      const result = {
        valid: true,
        source: 'published' as const,
        normalizedId: agentTemplate.id,
      }
      setCachedValidation(agentId, result)
      logger.debug({ agentId, normalizedId: agentTemplate.id }, 'Agent validated as published')
      return res.json(result)
    }

    // Agent not found
    logger.debug({ agentId }, 'Agent not found')
    return res.json({ valid: false })
  } catch (error) {
    logger.error(
      {
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
      },
      'Error in validateAgentNameHandler',
    )
    next(error)
  }
}
```

