import { API_KEY_ENV_VAR } from '@codebuff/common/constants'
import { yellow, red } from 'picocolors'
import { backendUrl } from '../config'
import { getUserCredentials } from '../credentials'
import { logger } from './logger'
import { Spinner } from './spinner'
import type { AgentTemplate } from '@codebuff/common/types/agent-template'

interface ValidateAgentResponse {
  valid: boolean
  source?: 'builtin' | 'published'
  normalizedId?: string
  message?: string
  issues?: any[]
}

/**
 * Validates an agent name against backend sources
 * @param agentId The agent ID to validate
 * @param loadedAgents Local agents to check first (short-circuit if found)
 * @returns true if valid or if validation fails (fail open), false if definitively invalid
 */
export async function validateAgent(
  agentId: string,
  loadedAgents: Record<string, AgentTemplate>,
): Promise<boolean> {
  // Check if agent exists in locally loaded agents first (short-circuit)
  if (agentId in loadedAgents) {
    logger.debug({ agentId }, 'Agent found in local agents, skipping backend validation')
    return true
  }

  try {
    const user = getUserCredentials()
    const apiKey = process.env[API_KEY_ENV_VAR]

    // Log available credentials for debugging
    logger.debug(
      {
        hasUserCredentials: !!user,
        hasApiKey: !!apiKey,
      },
      'Validating agent with backend',
    )

    Spinner.get().start('Checking agent...')

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    }

    // Add authentication headers if available
    if (user?.authToken) {
      headers['Authorization'] = `Bearer ${user.authToken}`
    }
    if (apiKey) {
      headers['X-API-Key'] = apiKey
    }

    const response = await fetch(
      `${backendUrl}/api/agents/validate-name?agentId=${encodeURIComponent(agentId)}`,
      {
        method: 'GET',
        headers,
      },
    )

    Spinner.get().stop()

    if (!response.ok) {
      logger.warn(
        {
          agentId,
          status: response.status,
          statusText: response.statusText,
        },
        'Agent validation request failed',
      )
      // Network error - warn but continue
      console.log(yellow('Warning: Could not validate agent name. Continuing anyway...'))
      return true
    }

    const data: ValidateAgentResponse = await response.json()

    if (!data.valid) {
      console.error(
        red(`\nError: Agent '${agentId}' not found. Please check the agent name and try again.\n`),
      )
      logger.warn({ agentId }, 'Agent validation failed - agent not found')
      process.exit(1)
    }

    logger.debug(
      {
        agentId,
        source: data.source,
        normalizedId: data.normalizedId,
      },
      'Agent validated successfully',
    )

    return true
  } catch (error) {
    Spinner.get().stop()

    logger.error(
      {
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : undefined,
        agentId,
      },
      'Error during agent validation',
    )

    // Network error - warn but continue (fail open)
    console.log(yellow('Warning: Could not validate agent name. Continuing anyway...'))
    return true
  }
}

/**
 * Validates agent definitions if user is authenticated
 * This is used for local agent definitions loaded from .agents directory
 */
export function validateAgentDefinitionsIfAuthenticated(
  agents: AgentTemplate[],
): void {
  const user = getUserCredentials()
  const apiKey = process.env[API_KEY_ENV_VAR]

  if (!user && !apiKey) {
    // Skip validation if not authenticated
    return
  }

  // Basic validation of agent definitions structure
  for (const agent of agents) {
    if (!agent.id || !agent.displayName) {
      logger.warn(
        {
          agentId: agent.id,
          displayName: agent.displayName,
        },
        'Invalid agent definition structure',
      )
    }
  }
}
```

