### 1. Create Terminal Command Execution Utility

**File: `sdk/src/tools/run-terminal-command.ts` (new file)**

```typescript
import { spawn } from 'child_process'
import { mkdtempSync, unlinkSync, writeFileSync } from 'fs'
import { tmpdir } from 'os'
import * as os from 'os'
import path, { join } from 'path'

const IS_WINDOWS = os.platform() === 'win32'

type UnixShell = 'bash' | 'zsh'
type WinShell = 'cmd.exe'
type ShellKind = UnixShell | WinShell

function selectShell(): ShellKind {
  if (IS_WINDOWS) {
    return 'cmd.exe'
  }
  return 'bash'
}

function buildEnv(): NodeJS.ProcessEnv {
  return {
    ...process.env,
    FORCE_COLOR: '3',
    CLICOLOR: '1',
    CLICOLOR_FORCE: '1',
    TERM: IS_WINDOWS ? 'cygwin' : 'xterm-256color',
  }
}

function buildInit(shell: ShellKind): string[] {
  if (IS_WINDOWS) {
    return []
  }

  if (shell === 'bash') {
    return [
      'shopt -s expand_aliases',
      'source ~/.bash_profile 2>/dev/null || true',
      'source ~/.profile 2>/dev/null || true',
      'source ~/.bashrc 2>/dev/null || true',
    ]
  }

  return []
}

function createWrapperScript(
  shell: UnixShell,
  initLines: string[],
  userCmd: string,
) {
  const tmp = mkdtempSync(join(tmpdir(), 'codebuff-'))
  const scriptPath = join(tmp, `cmd.${shell}`)

  const shebang = '#!/usr/bin/env bash'
  const aliasEnable = 'shopt -s expand_aliases'

  writeFileSync(
    scriptPath,
    [shebang, aliasEnable, ...initLines, '', userCmd, ''].join('\n'),
    { mode: 0o755 },
  )

  return scriptPath
}

function buildWinInvocation(
  shell: WinShell,
  initLines: string[],
  userCmd: string,
): { exe: string; args: string[] } {
  const init = initLines.join('; ')
  const cmdAll = init ? `${init}; ${userCmd}` : userCmd

  return { exe: 'cmd.exe', args: ['/d', '/s', '/c', cmdAll] }
}

function formatOutput(stdout: string, stderr: string, exitCode: number | null): string {
  let result = '```stdout\n'
  result += stdout
  result += '\n```\n\n'

  if (stderr) {
    result += '```stderr\n'
    result += stderr
    result += '\n```\n\n'
  }

  result += '```exit_code\n'
  result += String(exitCode ?? 'null')
  result += '\n```'

  return result
}

export async function runTerminalCommand(
  command: string,
  cwd: string,
  timeoutSeconds: number,
): Promise<{ success: boolean; output: { type: 'text'; value: string } }> {
  const shell = selectShell()
  const env = buildEnv()
  const initLines = buildInit(shell)

  return new Promise((resolve) => {
    let stdout = ''
    let stderr = ''
    let scriptPath: string | null = null

    const cleanupAndResolve = (exitCode: number | null, error?: string) => {
      if (scriptPath && !IS_WINDOWS) {
        try {
          unlinkSync(scriptPath)
        } catch {
          // ignore
        }
      }

      if (error) {
        resolve({
          success: false,
          output: {
            type: 'text',
            value: error,
          },
        })
      } else {
        resolve({
          success: true,
          output: {
            type: 'text',
            value: formatOutput(stdout, stderr, exitCode),
          },
        })
      }
    }

    let child
    try {
      if (IS_WINDOWS) {
        const { exe, args } = buildWinInvocation(shell as WinShell, initLines, command)
        child = spawn(exe, args, { cwd, env })
      } else {
        scriptPath = createWrapperScript(shell as UnixShell, initLines, command)
        child = spawn(shell, [scriptPath], { cwd, env })
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error)
      cleanupAndResolve(null, `Failed to spawn process: ${errorMessage}`)
      return
    }

    let timer: NodeJS.Timeout | null = null
    if (timeoutSeconds >= 0) {
      timer = setTimeout(() => {
        child.kill()
        cleanupAndResolve(124, `Command timed out after ${timeoutSeconds}s`)
      }, timeoutSeconds * 1000)
    }

    child.stdout.on('data', (data: Buffer) => {
      stdout += data.toString()
    })

    child.stderr.on('data', (data: Buffer) => {
      stderr += data.toString()
    })

    child.on('error', (error) => {
      if (timer) clearTimeout(timer)
      cleanupAndResolve(null, `Process error: ${error.message}`)
    })

    child.on('close', (code) => {
      if (timer) clearTimeout(timer)
      cleanupAndResolve(code)
    })
  })
}
```

