import { DEFAULT_ORG_PREFIX } from './agent-name-normalization'

/**
 * Resolve CLI agent ID based on user input and local agents.
 * 
 * - Returns undefined when input is undefined
 * - Preserves explicitly prefixed identifiers (containing '/') as-is
 * - Returns input as-is when it exists in local agent IDs
 * - Applies default organization prefix to unprefixed identifiers not found locally
 */
export function resolveCliAgentId(
  input: string | undefined,
  localAgentIds: string[],
): string | undefined {
  if (input === undefined) {
    return undefined
  }

  if (input.includes('/')) {
    return input
  }

  if (localAgentIds.includes(input)) {
    return input
  }

  return `${DEFAULT_ORG_PREFIX}${input}`
}
```

