```typescript
import { validateAgents } from '@codebuff/common/templates/agent-validation'
import { eq } from 'drizzle-orm'
import db from '@codebuff/common/db'
import * as schema from '@codebuff/common/db/schema'
import { z } from 'zod'
import { logger } from '../util/logger'

import type {
  Request as ExpressRequest,
  Response as ExpressResponse,
  NextFunction,
} from 'express'

const validateAgentsRequestSchema = z.object({
  agentConfigs: z.record(z.any()),
})

async function getUserIdFromSessionToken(
  sessionToken: string,
): Promise<string | undefined> {
  const user = await db
    .select({ userId: schema.user.id })
    .from(schema.user)
    .innerJoin(schema.session, eq(schema.user.id, schema.session.userId))
    .where(eq(schema.session.sessionToken, sessionToken))
    .then((users) => users[0]?.userId)
  return user
}

async function validateAgentsHandler(
  req: ExpressRequest,
  res: ExpressResponse,
  next: NextFunction,
): Promise<void | ExpressResponse> {
  try {
    const sessionToken = req.cookies?.['next-auth.session-token']

    if (!sessionToken) {
      return res.status(401).json({ error: 'Authentication required' })
    }

    const userId = await getUserIdFromSessionToken(sessionToken)
    if (!userId) {
      return res.status(401).json({ error: 'Invalid session' })
    }

    const { agentConfigs } = validateAgentsRequestSchema.parse(req.body)

    const { templates, validationErrors } = validateAgents(agentConfigs)

    return res.status(200).json({
      success: true,
      templates: Object.keys(templates),
      validationErrors,
    })
  } catch (error) {
    logger.error({ error }, 'Error handling /api/agents/validate request')
    if (error instanceof z.ZodError) {
      return res
        .status(400)
        .json({ error: 'Invalid request body', issues: error.errors })
    }
    next(error)
    return
  }
}

export default validateAgentsHandler
```

