```typescript
import { backendUrl } from '../config'
import { logger } from '../utils/logger'
import { User } from '@codebuff/common/util/credentials'

interface ValidationResult {
  success: boolean
  validationErrors?: Array<{ filePath: string; message: string }>
}

export async function validateAgentConfigs(
  agentConfigs: Record<string, any>,
  user: User | undefined,
): Promise<ValidationResult> {
  if (!user || !user.authToken) {
    return { success: true }
  }

  if (Object.keys(agentConfigs).length === 0) {
    return { success: true }
  }

  try {
    const response = await fetch(`${backendUrl}/api/agents/validate`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Cookie: `next-auth.session-token=${user.authToken}`,
      },
      body: JSON.stringify({
        agentConfigs,
      }),
    })

    if (!response.ok) {
      logger.warn(
        { status: response.status, statusText: response.statusText },
        'Agent validation request failed',
      )
      return { success: true }
    }

    const data = await response.json()

    if (data.validationErrors && data.validationErrors.length > 0) {
      console.warn('\n⚠️  Agent Template Validation Warnings:\n')
      for (const error of data.validationErrors) {
        console.warn(`❌ ${error.filePath}: ${error.message}`)
      }
      console.warn('')
    }

    return {
      success: true,
      validationErrors: data.validationErrors,
    }
  } catch (error) {
    logger.error(
      {
        errorMessage: error instanceof Error ? error.message : String(error),
        errorStack: error instanceof Error ? error.stack : undefined,
      },
      'Failed to validate agent configs',
    )
    return { success: true }
  }
}
