    const shellConfigFiles = loadShellConfigFiles()

    const { tokenScores, tokenCallers } = await getFileTokenScores(
      projectRoot,
      allFilePaths,
    )

    const codebuffConfig = loadCodebuffConfig()

    // Load agent templates with verbose: false to avoid console output during context loading
    const agentTemplates = await loadLocalAgents({ verbose: false })

    cachedProjectFileContext = {
      projectRoot,
      cwd: projectRoot,
      fileTree,
      fileTokenScores: tokenScores,
      tokenCallers,
      knowledgeFiles: knowledgeFilesWithScrapedContent,
      agentTemplates,
