      shellConfigFiles,
      systemInfo: getSystemInfo(),
      userKnowledgeFiles: userKnowledgeFilesWithScrapedContent,
      gitChanges,
      changesSinceLastChat,
      fileVersions: [],
    }
  }

  return cachedProjectFileContext
}
