### 1. Create `sdk/src/tools/read-files.ts`

This new file will contain the `getFiles` function with all the required functionality:

```typescript
import fs from 'fs'
import path from 'path'

import { FILE_READ_STATUS } from '../../../common/src/constants'

/**
 * Safely reads multiple files from the filesystem with size limits and path validation.
 * 
 * @param filePaths - Array of file paths to read (can be absolute or relative)
 * @param cwd - Current working directory (project root)
 * @returns Record mapping file paths to their content or status messages
 */
export function getFiles(
  filePaths: string[],
  cwd: string,
): Record<string, string | null> {
  const result: Record<string, string | null> = {}
  const MAX_FILE_SIZE = 1024 * 1024 // 1MB in bytes

  for (const filePath of filePaths) {
    if (!filePath) {
      continue
    }

    // Convert absolute paths within project to relative paths
    const relativePath = filePath.startsWith(cwd)
      ? path.relative(cwd, filePath)
      : filePath

    const fullPath = path.join(cwd, relativePath)

    // Check if file is outside project directory
    if (path.isAbsolute(relativePath) || !fullPath.startsWith(cwd)) {
      result[relativePath] = FILE_READ_STATUS.OUTSIDE_PROJECT
      continue
    }

    try {
      const stats = fs.statSync(fullPath)

      if (stats.size > MAX_FILE_SIZE) {
        result[relativePath] =
          FILE_READ_STATUS.TOO_LARGE +
          ` [${(stats.size / (1024 * 1024)).toFixed(2)}MB]`
      } else {
        const content = fs.readFileSync(fullPath, 'utf8')
        result[relativePath] = content
      }
    } catch (error) {
      if (
        error &&
        typeof error === 'object' &&
        'code' in error &&
        error.code === 'ENOENT'
      ) {
        result[relativePath] = FILE_READ_STATUS.DOES_NOT_EXIST
      } else {
        result[relativePath] = FILE_READ_STATUS.ERROR
      }
    }
  }

  return result
}
```

