import { execFileSync } from 'child_process'

import { API_KEY_ENV_VAR } from '../../common/src/constants'
import type { PrintModeEvent } from '../../common/src/types/print-mode'
import type { AgentTemplateType } from '../../common/src/types/session-state'
import { CODEBUFF_BINARY, isDevelopment, getWebSocketUrl } from './constants'
import { processStream } from './process-stream'

/**
 * @deprecated Use WebSocketHandler instead for more flexible WebSocket-based communication.
 * This client will be removed in a future version.
 */
export class CodebuffClient {
  public cwd: string

  constructor({ cwd }: { cwd: string }) {
    if (execFileSync('which', [CODEBUFF_BINARY]).toString().trim() === '') {
      throw new Error(
        'Codebuff binary not found. Please run "npm i -g codebuff"',
      )
    }
    if (!process.env[API_KEY_ENV_VAR]) {
      throw new Error(
        `Codebuff API key not found. Please set the ${API_KEY_ENV_VAR} environment variable.`,
      )
    }

    this.cwd = cwd
  }

  public async runNewChat({
    agent,
    prompt,
    params,
    handleEvent,
  }: {
    agent: AgentTemplateType
    prompt: string
    params?: Record<string, any>
    handleEvent: (event: PrintModeEvent) => void
  }): Promise<{ agentId: string }> {
    const args = [prompt, '-p', '--agent', agent]
    if (prompt) {
      args.push(prompt)
    }
    if (params) {
      args.push('--params', JSON.stringify(params))
    }
    if (this.cwd) {
      args.push('--cwd', this.cwd)
    }

    await processStream({
      codebuffArgs: args,
      handleEvent,
    })

    return {
      agentId: agent,
    }
  }
}

export interface WebSocketHandlerOptions {
  cwd: string
  apiKey?: string
  onOpen?: () => void
  onClose?: (event: CloseEvent) => void
  onError?: (event: Event) => void
  onMessage?: (event: MessageEvent) => void
  onReconnect?: () => void
}

export class WebSocketHandler {
  private ws: WebSocket | null = null
  private cwd: string
  private apiKey: string
  private options: WebSocketHandlerOptions
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectDelay = 1000

  constructor(options: WebSocketHandlerOptions) {
    this.cwd = options.cwd
    this.apiKey = options.apiKey || process.env[API_KEY_ENV_VAR] || ''
    this.options = options

    if (!this.apiKey) {
      throw new Error(
        `Codebuff API key not found. Please set the ${API_KEY_ENV_VAR} environment variable or pass it in options.`,
      )
    }
  }

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const wsUrl = getWebSocketUrl()
        this.ws = new WebSocket(wsUrl)

        this.ws.onopen = () => {
          this.reconnectAttempts = 0
          this.options.onOpen?.()
          resolve()
        }

        this.ws.onclose = (event) => {
          this.options.onClose?.(event)
          if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.scheduleReconnect()
          }
        }

        this.ws.onerror = (event) => {
          this.options.onError?.(event)
          reject(new Error('WebSocket connection failed'))
        }

        this.ws.onmessage = (event) => {
          this.options.onMessage?.(event)
        }
      } catch (error) {
        reject(error)
      }
    })
  }

  private scheduleReconnect(): void {
    setTimeout(() => {
      this.reconnectAttempts++
      this.connect().then(() => {
        this.options.onReconnect?.()
      })
    }, this.reconnectDelay * this.reconnectAttempts)
  }

  send(data: any): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(data))
    } else {
      throw new Error('WebSocket is not connected')
    }
  }

  close(): void {
    if (this.ws) {
      this.ws.close()
      this.ws = null
    }
  }

  isConnected(): boolean {
    return this.ws !== null && this.ws.readyState === WebSocket.OPEN
  }
}
