### 4. **Create User Profile Hook with localStorage Caching**

**File: `web/src/hooks/use-user-profile.ts`** (new file)

```typescript
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useSession } from 'next-auth/react'
import { useCallback, useEffect } from 'react'

import type { UserProfile } from '@/types/user'

const CACHE_KEY = 'codebuff_user_profile'
const QUERY_KEY = ['userProfile']

function serializeUserProfile(profile: UserProfile): string {
  return JSON.stringify({
    ...profile,
    created_at: profile.created_at ? profile.created_at.toISOString() : null,
  })
}

function deserializeUserProfile(data: string): UserProfile | null {
  const parsed = JSON.parse(data)
  return {
    ...parsed,
    created_at: parsed.created_at ? new Date(parsed.created_at) : null,
  }
}

function getCachedProfile(): UserProfile | null {
  if (typeof window === 'undefined') return null

  const cached = localStorage.getItem(CACHE_KEY)
  if (!cached) return null

  return deserializeUserProfile(cached)
}

function setCachedProfile(profile: UserProfile): void {
  if (typeof window === 'undefined') return

  localStorage.setItem(CACHE_KEY, serializeUserProfile(profile))
}

function clearCachedProfile(): void {
  if (typeof window === 'undefined') return

  localStorage.removeItem(CACHE_KEY)
}

export function useUserProfile() {
  const { data: session, status } = useSession()
  const queryClient = useQueryClient()

  const { data: userProfile, isLoading } = useQuery<UserProfile>({
    queryKey: QUERY_KEY,
    queryFn: async () => {
      const response = await fetch('/api/user/profile')
      if (!response.ok) throw new Error('Failed to fetch profile')
      const data = await response.json()

      const profile: UserProfile = {
        ...data,
        created_at: data.created_at ? new Date(data.created_at) : null,
      }

      setCachedProfile(profile)
      return profile
    },
    enabled: !!session?.user,
    initialData: () => {
      const cached = getCachedProfile()
      return cached ?? undefined
    },
    staleTime: 1000 * 60 * 5,
  })

  useEffect(() => {
    if (status === 'unauthenticated') {
      clearCachedProfile()
    }
  }, [status])

  const clearCache = useCallback(() => {
    clearCachedProfile()
    queryClient.invalidateQueries({ queryKey: QUERY_KEY })
  }, [queryClient])

  return {
    userProfile: userProfile ?? null,
    isLoading,
    clearCache,
  }
}
