export interface ToolCallRenderer {
  onToolStart?: (
    toolName: string,
    attributes: Record<string, string>,
  ) => string | null | (() => void)

  onParamStart?: (
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  onParamChunk?: (
    content: string,
    paramName: string,
    toolName: string,
  ) => string | null | (() => void)

  onParamEnd?: (
    paramName: string,
    toolName: string,
    content: string,
  ) => string | null | (() => void)

  onToolEnd?: (
    toolName: string,
    params: Record<string, string>,
  ) => string | null | (() => void)
}

function renderSpawnAgentsParam(content: string): string | null {
  let agents: SpawnAgentConfig[] = []
  try {
    agents = JSON.parse(content)
  } catch (e) {
    return null
  }
  if (agents.length > 0) {
    return gray(
      agents
        .map((props) => {
          const agentType = props?.agent_type
          const prompt = props?.prompt
          const client = Client.getInstance(false)
          const agentName =
            (client?.agentNames && client.agentNames[agentType]) || agentType

          if (!agentName) {
            return null
          }

          return `@${bold(agentName)}:\n${prompt || 'No prompt provided'}`
        })
        .filter((item) => item !== null)
        .join('\n\n') + '\n',
    )
  }
  return null
}

let toolStart = true

export const defaultToolCallRenderer: ToolCallRenderer = {
  onToolStart: (toolName) => {
    toolStart = true
    return '\n\n' + gray(`[${bold(snakeToTitleCase(toolName))}]`) + '\n'
  },

  onParamChunk: (content, paramName, toolName) => {
    if (toolStart && content.startsWith('\n')) content = content.slice(1)
    toolStart = false
    return gray(content)
  },

  onParamEnd: () => null,

  onToolEnd: () => '\n\n',
}

