const JsonSchemaSchema: z.ZodType<any> = z.lazy(() =>
  z
    .object({
      type: z.literal('object'),
      description: z.string().optional(),
      properties: z
        .record(
          JsonSchemaSchema.or(
            z
              .object({
                type: z.enum([
                  'string',
                  'number',
                  'integer',
                  'boolean',
                  'array',
                ]),
                description: z.string().optional(),
                enum: z.array(z.any()).optional(),
              })
              .passthrough(),
          ),
        )
        .optional(),
      required: z.array(z.string()).optional(),
    })
    .passthrough(),
)

