  // Reset regex state
  stringWithNewlinePattern.lastIndex = 0

  const replacements: Array<{ original: string; replacement: string }> = []

  while ((match = stringWithNewlinePattern.exec(content)) !== null) {
    const [fullMatch, propertyName, quote, stringContent] = match

    // Only process if the string contains \n
    if (!stringContent.includes('\\n')) {
      continue
    }

    // Convert escaped newlines to actual newlines
    let convertedContent = stringContent
      .replace(/\\n/g, '\n')
      .replace(/\\t/g, '\t')
      // Escape any existing backticks to prevent syntax errors
      .replace(/`/g, '\\`')
      // Preserve other escape sequences
      .replace(/\\\\/g, '\\\\')

    // Handle escaped quotes in the original string
    if (quote === "'") {
      convertedContent = convertedContent.replace(/\\'/g, "'")
    } else {
      convertedContent = convertedContent.replace(/\\"/g, '"')
    }

    // Create the template literal version
    const templateLiteral = `${propertyName}: \`${convertedContent}\``

    replacements.push({
      original: fullMatch,
      replacement: templateLiteral,
    })
  }

  // Apply all replacements
  for (const { original, replacement } of replacements) {
    result = result.replace(original, replacement)
  }

  return result
}

function processFile(filePath: string): ConversionResult {
  try {
    const content = readFileSync(filePath, 'utf8')
    const converted = convertEscapedNewlinesToTemplateLiterals(content)

    if (content !== converted) {
      writeFileSync(filePath, converted, 'utf8')
      return { filePath, modified: true }
    }

    return { filePath, modified: false }
  } catch (error) {
    return {
      filePath,
      modified: false,
      errorMessage: error instanceof Error ? error.message : String(error),
    }
  }
}

function main() {
  console.log('🔄 Converting escaped newlines to template literals...\n')

  const agentsDir = join(process.cwd(), '.agents')

  try {
    const files = readdirSync(agentsDir)
      .filter((file) => file.endsWith('.ts'))
      .map((file) => join(agentsDir, file))

    const results = files.map(processFile)

    const modified = results.filter((r) => r.modified)
    const errors = results.filter((r) => r.errorMessage)

    console.log('📊 Conversion Summary:')
    console.log(`   Total files processed: ${results.length}`)
    console.log(`   Files modified: ${modified.length}`)
    console.log(`   Errors: ${errors.length}`)

    if (modified.length > 0) {
      console.log('\n✅ Modified files:')
      modified.forEach((r) => {
        const fileName = r.filePath.split('/').pop()
        console.log(`   - ${fileName}`)
      })
    }

    if (errors.length > 0) {
      console.log('\n❌ Errors:')
      errors.forEach((r) => {
        const fileName = r.filePath.split('/').pop()
        console.log(`   - ${fileName}: ${r.errorMessage}`)
      })
    }

    if (modified.length === 0 && errors.length === 0) {
      console.log('\n✨ No changes needed - all files are already using proper formatting!')
    }
  } catch (error) {
    console.error('❌ Failed to process files:', error)
    process.exit(1)
  }
}

if (import.meta.main) {
  main()
}
```

